INSERT INTO public.content_lessons
  (id, chapter_id, title, lesson_type, description, sort_order, status, payload, published_at)
VALUES
  ('g5-c1-l1', 'g5-c1', 'Bài 1: Khái niệm, tính chất cơ bản & So sánh phân số', 'learn', 'Ôn tập cấu tạo phân số, tính chất cơ bản nhân/chia cùng một số, quy tắc so sánh phân số', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Chào mừng các bạn đến với Toán Lớp 5! Robot và Cú Mèo sẽ cùng các bạn chinh phục năm học cuối cấp tiểu học thật xuất sắc nhé! 🦉🤖"}},{"type":"visual","content":{"text":"- Phân số có tử số và mẫu số (khác 0). - Tính chất cơ bản: Nhân hoặc chia cả tử và mẫu với cùng số khác 0 được phân số bằng nó. - So sánh cùng mẫu: tử số lớn hơn thì lớn hơn. Khác mẫu: quy đồng rồi so sánh."}},{"type":"quiz","content":{"question":"Phân số nào sau đây bằng phân số 3/5?","options":["9/15","6/15","9/10","12/25"],"answer":"9/15","mascotHint":"Nhân cả tử và mẫu với 3: 3×3 / 5×3 = 9/15!"}},{"type":"quiz","content":{"question":"Trong các phân số 4/7; 5/7; 3/7; 6/7, phân số lớn nhất là:","options":["6/7","5/7","4/7","3/7"],"answer":"6/7","mascotHint":"Cùng mẫu số 7, tử số 6 lớn nhất nên 6/7 lớn nhất!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Phân số tối giản không thể rút gọn thêm.","So sánh với 1: Tử < Mẫu, nên là bé hơn 1; Tử > Mẫu, nên là lớn hơn 1."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c1-l2', 'g5-c1', 'Bài 2: Phân số thập phân', 'learn', 'Các phân số có mẫu số là 10, 100, 1000... gọi là phân số thập phân', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Các phân số như 3/10, 25/100, 125/1000 có mẫu số là 10, 100, 1000... được gọi là PHÂN SỐ THẬP PHÂN! 💡"}},{"type":"visual","content":{"text":"Chuyển phân số thường thành phân số thập phân: - 1/2 = (1×5)/(2×5) = 5/10 - 3/4 = (3×25)/(4×25) = 75/100 - 7/20 = (7×5)/(20×5) = 35/100"}},{"type":"quiz","content":{"question":"Chuyển phân số 2/5 thành phân số thập phân có mẫu số 10:","options":["4/10","2/10","5/10","6/10"],"answer":"4/10","mascotHint":"Nhân cả tử và mẫu với 2: (2×2)/(5×2) = 4/10!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Phân số thập phân có mẫu số là 10, 100, 1000...","Muốn chuyển về phân số thập phân: tìm số nhân sao cho mẫu là 10, 100, 1000..."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c1-l3', 'g5-c1', 'Bài 3: Ôn tập bốn phép tính với phân số', 'learn', 'Cộng, trừ, nhân, chia phân số và bài toán tìm phân số của một số', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Cùng Robot ôn lại 4 phép tính phân số: - Cộng/trừ: quy đồng rồi tính. - Nhân: tử × tử, mẫu × mẫu. - Chia: nhân với phân số đảo ngược! 🔄"}},{"type":"visual","content":{"text":"Ví dụ tổng hợp: - 2/3 + 1/4 = 8/12 + 3/12 = 11/12 - 3/5 × 10/9 = (3×10)/(5×9) = 30/45 = 2/3 - 2/7 : 4/5 = 2/7 × 5/4 = 10/28 = 5/14"}},{"type":"quiz","content":{"question":"Tính: 3/4 - 1/3 = ?","options":["5/12","2/1","2/12","1/12"],"answer":"5/12","mascotHint":"9/12 - 4/12 = 5/12!"}},{"type":"quiz","content":{"question":"Tìm 3/5 của 45 kg:","options":[27,25,30,35],"answer":27,"mascotHint":"45 × 3/5 = (45 × 3) : 5 = 27 kg!"}},{"type":"summary","content":{"title":"Quy tắc cốt lõi:","points":["Nhân: Tử nhân tử, mẫu nhân mẫu.","Chia: Lấy phân số thứ nhất nhân phân số thứ hai đảo ngược."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c1-l4', 'g5-c1', 'Bài 4: Hỗn số và các phép tính với hỗn số', 'learn', 'Khái niệm hỗn số gồm phần nguyên và phần phân số; cách chuyển hỗn số thành phân số', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Có 2 cái bánh nguyên và 3/4 cái bánh, ta viết là 2 3/4 (đọc là hai và ba phần tư)! Đó chính là HỖN SỐ! 🥞"}},{"type":"visual","content":{"text":"Chuyển hỗn số thành phân số: Tử số = (Phần nguyên × Mẫu số) + Tử số cũ Mẫu số = Giữ nguyên mẫu số cũ Ví dụ: 2 3/4 = (2 × 4 + 3) / 4 = 11/4"}},{"type":"quiz","content":{"question":"Chuyển hỗn số 3 1/2 thành phân số:","options":["7/2","5/2","6/2","4/2"],"answer":"7/2","mascotHint":"(3 × 2 + 1) / 2 = 7/2!"}},{"type":"summary","content":{"title":"Công thức chuyển hỗn số:","points":["Tử số mới = Phần nguyên × Mẫu + Tử.","Mẫu số mới giữ nguyên."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c1-l5', 'g5-c1', 'Bài 5: Ôn tập và bổ sung về giải toán (Tỉ lệ thuận & nghịch)', 'learn', 'Phương pháp rút về đơn vị và phương pháp tìm tỉ số', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"thinking","text":"Hai đại lượng tỉ lệ thuận: cái này tăng bao nhiêu lần thì cái kia tăng bấy nhiêu lần (mua nhiều bút tốn nhiều tiền). Tỉ lệ nghịch: cái này tăng bao nhiêu lần thì cái kia GIẢM bấy nhiêu lần (nhiều người làm thì tốn ít ngày)! ⚖️"}},{"type":"visual","content":{"text":"Ví dụ (Tỉ lệ thuận): Mua 5 quyển vở hết 40 000 đồng. Mua 8 quyển vở hết bao nhiêu tiền? Cách 1: Rút về đơn vị: 1 quyển hết 40 000 : 5 = 8 000 đồng, nên là 8 quyển hết 8 000 × 8 = 64 000 đồng."}},{"type":"quiz","content":{"question":"Một ô tô đi trong 2 giờ được 90 km. Hỏi với vận tốc đó, ô tô đi trong 4 giờ được bao nhiêu km?","options":[180,160,200,135],"answer":180,"mascotHint":"Thời gian gấp 4 : 2 = 2 lần, nên quãng đường = 90 × 2 = 180 km!"}},{"type":"quiz","content":{"question":"Có 10 người đắp xong đoạn đường trong 6 ngày. Hỏi muốn đắp xong trong 3 ngày cần bao nhiêu người? (Mức làm như nhau)","options":[20,15,12,18],"answer":20,"mascotHint":"Tỉ lệ nghịch: Thời gian giảm 6 : 3 = 2 lần, nên số người phải gấp 2 lần: 10 × 2 = 20 người!"}},{"type":"summary","content":{"title":"Ghi nhớ 2 phương pháp:","points":["Phương pháp 1: Rút về đơn vị.","Phương pháp 2: Tìm tỉ số."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c1-l6', 'g5-c1', 'Bài 6: Bảng đơn vị đo độ dài & Bảng đơn vị đo khối lượng', 'learn', 'Hệ thống hóa km, hm, dam, m, dm, cm, mm và tấn, tạ, yến, kg, hg, dag, g', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Hai đơn vị đo độ dài (hoặc khối lượng) liền kề hơn kém nhau đúng 10 lần! Đơn vị lớn gấp 10 lần đơn vị bé, đơn vị bé bằng 1/10 đơn vị lớn! 📏"}},{"type":"visual","content":{"text":"- Bảng độ dài: km > hm > dam > m > dm > cm > mm (mỗi bước ×10 hoặc :10) - Bảng khối lượng: tấn > tạ > yến > kg > hg > dag > g"}},{"type":"quiz","content":{"question":"3 km 50 m bằng bao nhiêu mét?","options":[3050,3500,3005,350],"answer":3050,"mascotHint":"3 km = 3000 m. 3000 + 50 = 3050 m!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Mỗi đơn vị đo độ dài/khối lượng gấp 10 lần đơn vị bé hơn liền kề.","Mỗi đơn vị bé bằng 1/10 (hay 0,1) đơn vị lớn liền kề."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c1-l7', 'g5-c1', 'Bài 7: Đề-ca-mét vuông (dam²), Héc-tô-mét vuông (hm²)', 'learn', 'Các đơn vị đo diện tích đất: 1 dam² = 100 m²; 1 hm² = 100 dam² = 10 000 m²', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Đề-ca-mét vuông (dam²) là diện tích hình vuông cạnh 1 dam (10 m). Héc-tô-mét vuông (hm²) là diện tích hình vuông cạnh 1 hm (100 m)! 🟩"}},{"type":"visual","content":{"text":"Bảng đơn vị đo diện tích: km² > hm² > dam² > m² > dm² > cm² > mm² Chú ý: Hai đơn vị đo diện tích liền nhau hơn kém nhau 100 LẦN! 1 hm² = 100 dam² = 10 000 m²"}},{"type":"quiz","content":{"question":"2 hm² bằng bao nhiêu mét vuông?","options":[20000,2000,200,200000],"answer":20000,"mascotHint":"1 hm² = 10 000 m² nên 2 hm² = 20 000 m²!"}},{"type":"summary","content":{"title":"Ghi nhớ bảng diện tích:","points":["Mỗi đơn vị đo diện tích gấp 100 lần đơn vị bé hơn liền sau.","1 hm² = 100 dam² = 10 000 m²."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c1-l8', 'g5-c1', 'Bài 8: Héc-ta (ha)', 'learn', 'Đơn vị đo diện tích đất nông, lâm nghiệp: 1 ha = 1 hm² = 10 000 m²', 7, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Trong đời sống thực tế, người ta thường dùng đơn vị Héc-ta (viết tắt là ha) để đo diện tích các trang trại, cánh đồng lúa, cánh rừng! 🌾🌲"}},{"type":"visual","content":{"text":"Quy đổi héc-ta: 1 ha = 1 hm² = 10 000 m² 1 km² = 100 ha Một sân bóng đá tiêu chuẩn có diện tích gần bằng 1 ha đấy!"}},{"type":"quiz","content":{"question":"Khu rừng có diện tích 5 ha, diện tích khu rừng đó bằng bao nhiêu mét vuông?","options":["50 000 m²","5 000 m²","500 m²","500 000 m²"],"answer":"50 000 m²","mascotHint":"1 ha = 10 000 m² nên 5 ha = 50 000 m²!"}},{"type":"quiz","content":{"question":"Đổi: 4 km² = ... ha","options":[400,40,4000,40000],"answer":400,"mascotHint":"1 km² = 100 ha nên 4 km² = 400 ha!"}},{"type":"summary","content":{"title":"Ghi nhớ héc-ta:","points":["1 ha = 10 000 m²","1 km² = 100 ha"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c1-l10', 'g5-c1', 'Bài 9: Luyện tập so sánh phân số', 'learn', 'Ba mẹo so sánh phân số nhanh và chính xác', 8, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Có ba mẹo so sánh phân số cực nhanh: so với 1, quy đồng mẫu số và dùng phân số trung gian! ⚡"}},{"type":"concept","content":{"badge":"Ba Mẹo So Sánh","title":"So sánh phân số nhanh","points":["So với 1: tử bé hơn mẫu ⇒ bé hơn 1; tử lớn hơn mẫu ⇒ lớn hơn 1.","Quy đồng mẫu số rồi so sánh tử số (mẫu đã bằng nhau).","Cùng tử số: phân số nào có mẫu bé hơn thì lớn hơn."],"rule":"So với 1 trước — đó là mẹo nhanh nhất và ít sai nhất."}},{"type":"quiz","content":{"question":"Không cần quy đồng, phân số nào sau đây lớn hơn 1?","options":["7/5","3/4","5/9","2/3"],"answer":"7/5","mascotHint":"7 lớn hơn 5 nên 7/5 lớn hơn 1; còn 3/4, 5/9, 2/3 đều bé hơn 1!"}},{"type":"quiz","content":{"question":"So sánh hai phân số cùng tử số: 5/6 và 5/9","options":["5/6 > 5/9","5/6 < 5/9","5/6 = 5/9"],"answer":"5/6 > 5/9","mascotHint":"Cùng tử số 5, phân số nào có mẫu số bé hơn thì lớn hơn ⇒ 5/6 > 5/9!"}},{"type":"summary","content":{"title":"Ghi nhớ so sánh:","points":["Cùng tử số: mẫu bé hơn thì phân số lớn hơn","Cùng mẫu số: tử lớn hơn thì phân số lớn hơn"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c1-l11', 'g5-c1', 'Bài 10: Ôn tập tìm hai số khi biết Tổng (Hiệu) và Tỉ số', 'learn', 'Ôn lại hai dạng toán điển hình trước khi học giải toán tỉ lệ', 9, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Đây là dạng toán quan trọng nhất của phần ''ôn tập và bổ sung về giải toán'' — cùng làm cho thật chắc! 🎯"}},{"type":"concept","content":{"badge":"Hai Dạng Toán Tỉ","title":"Phân biệt và cách giải","points":["Đề cho tổng ⇒ chia cho TỔNG số phần. Đề cho hiệu ⇒ chia cho HIỆU số phần.","Ví dụ tổng: tổng 120, tỉ số 2 : 3 ⇒ một phần = 120 : 5 = 24 ⇒ hai số là 48 và 72.","Ví dụ hiệu: hiệu 36, tỉ số 1 : 4 ⇒ một phần = 36 : 3 = 12 ⇒ hai số là 12 và 48."],"rule":"Sau khi giải, thử lại bằng cách cộng (hoặc trừ) hai số vừa tìm."}},{"type":"quiz","content":{"question":"Tổng hai số là 120, tỉ số của hai số là 2 : 3. Số lớn là bao nhiêu?","options":[72,48,24,60],"answer":72,"mascotHint":"2 + 3 = 5 phần; 120 : 5 = 24 ⇒ số lớn = 24 × 3 = 72!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Tổng ⇒ chia cho tổng số phần","Hiệu ⇒ chia cho hiệu số phần"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c1-l12', 'g5-c1', 'Bài 11: Luyện tập bảng đơn vị đo diện tích', 'learn', 'Luyện quy đổi các đơn vị đo diện tích', 10, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Bảng đơn vị đo diện tích có một điều đặc biệt: hai đơn vị liền nhau hơn kém nhau 100 lần! 📐"}},{"type":"concept","content":{"badge":"Luyện Bảng Diện Tích","title":"Thứ tự và cách quy đổi","points":["Thứ tự: km² > hm² (ha) > dam² > m² > dm² > cm² > mm².","Hai đơn vị liền nhau hơn kém nhau 100 lần.","Ví dụ: 1 dam² = 100 m²; 1 hm² = 100 dam² = 10 000 m²."],"rule":"Đơn vị lớn gấp 100 lần đơn vị bé liền sau; đơn vị bé bằng 1/100 đơn vị lớn liền trước."}},{"type":"quiz","content":{"question":"1 dam² bằng bao nhiêu mét vuông?","options":[100,10,1000,10000],"answer":100,"mascotHint":"Hai đơn vị đo diện tích liền nhau hơn kém nhau 100 lần: 1 dam² = 100 m²!"}},{"type":"summary","content":{"title":"Ghi nhớ bảng diện tích:","points":["km² > hm² > dam² > m² > dm² > cm² > mm²","Mỗi bước nhảy là 100 lần (khác với đo độ dài chỉ 10 lần)"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c1-l9', 'g5-c1', 'Bài 12: Luyện tập chung Chương 1', 'learn', 'Tổng kết kiến thức phân số, toán tỉ lệ và bảng đơn vị đo diện tích', 11, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"proud","text":"Bé đã hoàn thành xuất sắc Chương 1! Cùng Cú Mèo làm bài thử thách tổng kết nào! 🏅"}},{"type":"concept","content":{"badge":"Kiến Thức Trọng Tâm","title":"Luyện tập chung Chương 1","explanation":"Luyện tập chung các kiến thức về số của chương 1.","points":["So sánh số thập phân: so phần nguyên trước, rồi so từng hàng phần thập phân.","Đổi phân số thập phân thành số thập phân: 3/10 = 0,3.","Viết số đo độ dài, khối lượng dưới dạng số thập phân."],"rule":"Đọc kỹ yêu cầu để biết cần viết dạng phân số hay số thập phân."}},{"type":"quiz","content":{"question":"Một mảnh đất hình chữ nhật có chiều dài 200 m, chiều rộng 100 m. Diện tích mảnh đất đó là bao nhiêu héc-ta?","options":["2 ha","20 ha","0,2 ha","200 ha"],"answer":"2 ha","mascotHint":"Diện tích = 200 × 100 = 20 000 m². 20 000 m² = 2 ha!"}},{"type":"summary","content":{"title":"Hoàn thành Chương 1:","points":["Vững vàng phân số và hỗn số.","Thành thạo chuyển đổi đơn vị đo diện tích và ha."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c2-l1', 'g5-c2', 'Bài 1: Khái niệm & Hàng của số thập phân', 'learn', 'Phần nguyên đứng trước dấu phẩy, phần thập phân đứng sau; hàng phần mười, hàng phần trăm, hàng phần nghìn', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Mỗi số thập phân gồm hai phần: Phần nguyên (bên trái dấu phẩy) và Phần thập phân (bên phải dấu phẩy)! Ví dụ: 8,56 gồm phần nguyên 8 và phần thập phân 56 phần trăm! 🎯"}},{"type":"visual","content":{"text":"Cấu tạo số thập phân 375,429: - Phần nguyên: 3 trăm, 7 chục, 5 đơn vị - Dấu phẩy ngăn cách - Phần thập phân: 4 phần mười (hàng phần mười), 2 phần trăm (hàng phần trăm), 9 phần nghìn (hàng phần nghìn)"}},{"type":"quiz","content":{"question":"Trong số thập phân 18,256, chữ số 5 thuộc hàng nào?","options":["Hàng phần trăm","Hàng phần mười","Hàng phần nghìn","Hàng chục"],"answer":"Hàng phần trăm","mascotHint":"Đứng ngay sau dấu phẩy là phần mười (2), tiếp theo là phần trăm (5)!"}},{"type":"quiz","content":{"question":"Phân số thập phân 7/100 viết dưới dạng số thập phân là:","options":["0,07","0,7","7,0","0,007"],"answer":"0,07","mascotHint":"Mẫu số có hai chữ số 0 nên có 2 chữ số sau dấu phẩy: 0,07!"}},{"type":"summary","content":{"title":"Ghi nhớ cấu tạo:","points":["Phần nguyên bên trái, phần thập phân bên phải dấu phẩy.","Các hàng phần thập phân: phần mười, phần trăm, phần nghìn..."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c2-l2', 'g5-c2', 'Bài 2: Số thập phân bằng nhau & So sánh số thập phân', 'learn', 'Thêm hoặc bớt chữ số 0 ở bên phải phần thập phân giá trị không đổi; so sánh phần nguyên trước rồi đến phần thập phân', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Nếu viết thêm (hoặc xóa bớt) chữ số 0 ở tận cùng bên phải phần thập phân thì được một số thập phân bằng nó! Ví dụ: 0,9 = 0,90 = 0,900! ✨"}},{"type":"concept","content":{"badge":"Quy Tắc So Sánh","title":"Cách so sánh hai số thập phân","explanation":"Để so sánh hai số thập phân, ta thực hiện theo thứ tự:","points":["Bước 1: So sánh phần nguyên trước. Số nào có phần nguyên lớn hơn thì số đó lớn hơn (ví dụ: 12,5 > 9,89).","Bước 2: Nếu phần nguyên bằng nhau, so sánh hàng phần mười. Số nào có hàng phần mười lớn hơn thì lớn hơn.","Bước 3: Nếu hàng phần mười bằng nhau, tiếp tục so sánh hàng phần trăm, hàng phần nghìn..."],"rule":"Không được đếm số lượng chữ số để so sánh! 0,5 = 0,50 lớn hơn 0,15."}},{"type":"dialogue","content":{"badge":"Giao Lưu Lớp Học","title":"Hiểu lầm kinh điển: 0,5 và 0,15","dialogueList":[{"character":"robot","name":"Bạn Rô-bốt 🤖","text":"Tớ thấy 15 lớn hơn 5, nên chắc chắn số 0,15 phải lớn hơn số 0,5 rồi!"},{"character":"nam","name":"Bạn Nam 👦","text":"Cậu nhầm to rồi Rô-bốt ơi! Phải so sánh từ hàng phần mười trước chứ!"}],"question":"Bạn Rô-bốt nói đúng hay sai?","options":["Đúng rồi 👍","Sai rồi 👎"],"correctAnswer":"Sai rồi 👎","explanation":"Rô-bốt đã mắc phải lỗi sai rất phổ biến! Ta có 0,5 = 0,50 (50 phần trăm), trong khi 0,15 chỉ có 15 phần trăm. So sánh hàng phần mười: 5 lớn hơn 1, do đó 0,5 lớn hơn 0,15!"}},{"type":"quiz","content":{"question":"Điền dấu thích hợp: 7,85 ... 7,9","options":["<",">","="],"answer":"<","mascotHint":"Phần nguyên bằng 7. Hàng phần mười: 8 < 9 nên 7,85 < 7,90!"}},{"type":"quiz","content":{"question":"Số nào bé nhất trong các số: 5,4; 5,04; 5,404; 5,004?","options":["5,004","5,04","5,4","5,404"],"answer":"5,004","mascotHint":"Hàng phần nghìn nhỏ nhất: 5,004 có phần thập phân 0,004 bé nhất!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["0,5 = 0,50 = 0,500.","So sánh phần nguyên trước; nếu bằng nhau thì so sánh hàng phần mười, phần trăm..."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c2-l3', 'g5-c2', 'Bài 3: Viết số đo đại lượng dưới dạng số thập phân', 'learn', 'Viết số đo độ dài, khối lượng, diện tích bằng số thập phân (ví dụ: 3 m 5 dm = 3,5 m)', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Số thập phân giúp ta viết số đo đại lượng vô cùng gọn gàng! Ví dụ: 2 m 7 cm = 2 và 7/100 m = 2,07 m! 📏"}},{"type":"visual","content":{"text":"Cách chuyển đổi: - Độ dài: 5 m 6 dm = 5,6 m; 4 km 250 m = 4,25 km - Khối lượng: 2 kg 50 g = 2,05 kg; 3 tấn 500 kg = 3,5 tấn - Diện tích: 4 m² 25 dm² = 4,25 m² (vì 1 m² = 100 dm²)"}},{"type":"quiz","content":{"question":"Viết số đo 3 m 45 cm dưới dạng số thập phân có đơn vị là mét:","options":["3,45 m","34,5 m","0,345 m","3,045 m"],"answer":"3,45 m","mascotHint":"45 cm = 45/100 m = 0,45 m, nên là 3,45 m!"}},{"type":"summary","content":{"title":"Ghi nhớ quy tắc đổi:","points":["Xác định mối quan hệ giữa 2 đơn vị.","Viết dưới dạng hỗn số rồi chuyển sang số thập phân."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c2-l4', 'g5-c2', 'Bài 4: Phép cộng số thập phân & Tổng nhiều số', 'learn', 'Đặt tính sao cho các chữ số ở cùng một hàng và dấu phẩy thẳng cột với nhau', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Quy tắc vàng khi cộng số thập phân: Đặt các dấu phẩy thẳng cột với nhau! Cộng như cộng số tự nhiên rồi hạ dấu phẩy thẳng cột xuống kết quả! ➕"}},{"type":"visual","content":{"text":"Đặt tính cộng: 15,82 + 9,35 -------- 25,17 (Hạ dấu phẩy thẳng cột xuống giữa 25 và 17)"}},{"type":"quiz","content":{"question":"Tính: 38,5 + 24,15 = ?","options":["62,65","62,20","63,65","62,55"],"answer":"62,65","mascotHint":"38,50 + 24,15 = 62,65!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Dấu phẩy thẳng cột.","Cộng như số tự nhiên, nhớ hạ dấu phẩy."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c2-l5', 'g5-c2', 'Bài 5: Phép trừ hai số thập phân', 'learn', 'Đặt tính dấu phẩy thẳng cột; thêm số 0 vào phần thập phân nếu cần để trừ', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Khi trừ số thập phân, nếu số chữ số phần thập phân của số bị trừ ít hơn số trừ, ta có thể viết thêm các chữ số 0 vào bên phải để trừ dễ dàng! ➖"}},{"type":"visual","content":{"text":"Ví dụ: 45,8 - 19,25 Viết thành: 45,80 - 19,25 = 26,55"}},{"type":"quiz","content":{"question":"Tính: 50 - 23,75 = ?","options":["26,25","27,25","26,35","27,35"],"answer":"26,25","mascotHint":"50,00 - 23,75 = 26,25!"}},{"type":"summary","content":{"title":"Ghi nhớ phép trừ:","points":["Viết thêm số 0 vào bên phải phần thập phân nếu cần.","Dấu phẩy luôn thẳng hàng."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c2-l6', 'g5-c2', 'Bài 6: Phép nhân số thập phân', 'learn', 'Nhân như nhân số tự nhiên; đếm số chữ số phần thập phân của cả hai thừa số để tách dấu phẩy', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Quy tắc nhân số thập phân: Nhân như số tự nhiên! Sau đó đếm xem trong phần thập phân của cả hai thừa số có bao nhiêu chữ số rồi dùng dấu phẩy tách ở tích ra bấy nhiêu chữ số kể từ phải sang trái! ✖️"}},{"type":"visual","content":{"text":"Ví dụ: 2,35 × 1,4 - Nhân 235 × 14 = 3290 - Hai thừa số có 2 + 1 = 3 chữ số ở phần thập phân - Tách 3 chữ số từ phải sang trái: 3,290 = 3,29 Nhân nhẩm với 10, 100, 1000: Dịch dấu phẩy sang phải 1, 2, 3 chữ số!"}},{"type":"quiz","content":{"question":"Tính: 3,45 × 10 = ?","options":[34.5,345,0.345,3450],"answer":34.5,"mascotHint":"Chuyển dấu phẩy sang bên phải một chữ số: 34,5!"}},{"type":"quiz","content":{"question":"Tính: 1,2 × 0,4 = ?","options":[0.48,4.8,0.048,48],"answer":0.48,"mascotHint":"12 × 4 = 48. Có 1 + 1 = 2 chữ số thập phân, nên là 0,48!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Nhân như số tự nhiên.","Đếm tổng số chữ số thập phân của 2 thừa số rồi tách ở tích."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c2-l7', 'g5-c2', 'Bài 7: Phép chia số thập phân', 'learn', 'Chia số thập phân cho số tự nhiên; chia cho 10, 100; chia số tự nhiên cho số tự nhiên ra thương thập phân; chia cho số thập phân', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"thinking","text":"Chia số thập phân cho số tự nhiên: Chia phần nguyên trước, trước khi lấy chữ số đầu tiên của phần thập phân thì viết dấu phẩy vào bên phải thương! ➗"}},{"type":"visual","content":{"text":"Chia cho số thập phân (ví dụ: 12 : 2,5): - Số chia có 1 chữ số thập phân, ta chuyển dấu phẩy ở cả hai số sang phải 1 vị trí: thành 120 : 25 = 4,8! Chia nhẩm cho 10, 100, 1000: Dịch dấu phẩy sang TRÁI 1, 2, 3 chữ số."}},{"type":"quiz","content":{"question":"Tính: 45,6 : 10 = ?","options":[4.56,456,0.456,45.6],"answer":4.56,"mascotHint":"Dịch dấu phẩy sang trái 1 chữ số: 4,56!"}},{"type":"quiz","content":{"question":"Tính: 15 : 4 = ?","options":[3.75,3.5,3.25,4],"answer":3.75,"mascotHint":"15 : 4 = 3 dư 3. Thêm dấu phẩy và thêm 0: 30 : 4 = 7 dư 2; 20 : 4 = 5, nên là 3,75!"}},{"type":"summary","content":{"title":"Ghi nhớ phép chia:","points":["Đặt dấu phẩy vào thương ngay khi chia sang phần thập phân.","Bỏ dấu phẩy ở số chia bằng cách chuyển dấu phẩy ở cả 2 số sang phải."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c2-l8', 'g5-c2', 'Bài 8: Tỉ số phần trăm', 'learn', 'Khái niệm tỉ số phần trăm và ký hiệu % (1% = 1/100)', 7, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"1 phần trăm viết là 1%! 100 phần trăm là 100% (toàn bộ). Tỉ số phần trăm xuất hiện khắp nơi trong đời sống: giảm giá 20%, pin điện thoại 85%! 📱🏷️"}},{"type":"visual","content":{"text":"Cách viết: - 1/100 = 0,01 = 1% - 35/100 = 0,35 = 35% - 3/4 = 75/100 = 75% Muốn tìm tỉ số phần trăm của hai số a và b: 1. Tìm thương của a và b: a : b 2. Nhân thương đó với 100 và viết thêm ký hiệu %."}},{"type":"quiz","content":{"question":"Tỉ số phần trăm của 3 và 5 là:","options":["60%","30%","50%","75%"],"answer":"60%","mascotHint":"3 : 5 = 0,6 = 60%!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["a : b = thương, nên là thương × 100 rồi thêm ký hiệu %.","100% = 1."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c2-l9', 'g5-c2', 'Bài 9: Giải toán về tỉ số phần trăm (3 bài toán cơ bản)', 'learn', '1. Tìm tỉ số % của 2 số; 2. Tìm giá trị % của 1 số; 3. Tìm 1 số biết giá trị % của nó', 8, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"3 bài toán tỉ số phần trăm kinh điển: 1. Tìm tỉ số %: a : b × 100% 2. Tìm a% của B: B × a : 100 3. Tìm số biết a% là B: B : a × 100! 💡"}},{"type":"visual","content":{"text":"Ví dụ: Lớp có 40 học sinh, trong đó có 60% là nữ. Số học sinh nữ là: 40 × 60 : 100 = 24 học sinh."}},{"type":"quiz","content":{"question":"Tìm 25% của 80 kg gạo:","options":[20,25,30,15],"answer":20,"mascotHint":"80 × 25 : 100 = 20 kg!"}},{"type":"quiz","content":{"question":"Biết 30% của một số là 45. Số đó là:","options":[150,120,135,160],"answer":150,"mascotHint":"45 : 30 × 100 = 1,5 × 100 = 150!"}},{"type":"summary","content":{"title":"3 Công thức vàng:","points":["Dạng 1: a : b × 100%","Dạng 2: B × % : 100","Dạng 3: B : % × 100"],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c2-l10', 'g5-c2', 'Bài 10: Máy tính bỏ túi & Luyện tập chung Chương 2', 'learn', 'Làm quen các phím cơ bản trên máy tính bỏ túi và ôn tập số thập phân', 9, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Máy tính bỏ túi là công cụ đắc lực giúp kiểm tra lại kết quả tính toán nhanh chóng! Nhớ sử dụng phím ON/C để bật và xóa màn hình nhé! 📲"}},{"type":"concept","content":{"badge":"Kiến Thức Trọng Tâm","title":"Máy tính bỏ túi & Luyện tập chung Chương 2","explanation":"Luyện tập chung các phép tính với số thập phân và dùng máy tính bỏ túi.","points":["Cộng, trừ, nhân, chia số thập phân: đặt tính như số tự nhiên rồi đặt dấu phẩy đúng vị trí.","Máy tính bỏ túi giúp kiểm tra lại kết quả đã tính.","Tỉ số phần trăm: 25% của 80 bằng 80 × 25 : 100 = 20."],"rule":"Máy tính chỉ để kiểm tra kết quả, không thay cho việc tự tính."}},{"type":"quiz","content":{"question":"Tính nhẩm: 4,5 × 0,1 = ?","options":[0.45,45,0.045,4.5],"answer":0.45,"mascotHint":"Nhân với 0,1 bằng chia cho 10: 4,5 : 10 = 0,45!"}},{"type":"summary","content":{"title":"Tổng kết Chương 2:","points":["Thành thạo 4 phép tính với số thập phân.","Vận dụng linh hoạt 3 bài toán tỉ số phần trăm."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c3-l1', 'g5-c3', 'Bài 1: Hình tam giác & Diện tích hình tam giác', 'learn', 'Đáy và đường cao tương ứng; Công thức diện tích S = (a × h) : 2', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Muốn tính diện tích hình tam giác: Lấy độ dài đáy nhân với chiều cao (cùng đơn vị đo) rồi chia cho 2! 📐"}},{"type":"visual","content":{"text":"Công thức: S = (a × h) : 2 Trong đó: a là độ dài đáy, h là chiều cao tương ứng."}},{"type":"quiz","content":{"question":"Một hình tam giác có đáy 10 cm và chiều cao 8 cm. Diện tích của hình tam giác là:","options":["40 cm²","80 cm²","20 cm²","18 cm²"],"answer":"40 cm²","mascotHint":"S = (10 × 8) : 2 = 80 : 2 = 40 cm²!"}},{"type":"summary","content":{"title":"Công thức tam giác:","points":["S = (đáy × cao) : 2","Độ dài đáy = (S × 2) : h; Chiều cao = (S × 2) : a"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c3-l2', 'g5-c3', 'Bài 2: Hình thang & Diện tích hình thang', 'learn', 'Đáy lớn, đáy bé, chiều cao; Công thức diện tích S = ((a + b) × h) : 2', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Bài ca hình thang quen thuộc: Muốn tính diện tích hình thang / Đáy lớn đáy bé ta mang cộng vào / Thế rồi nhân với chiều cao / Chia đôi lấy nửa thế nào cũng ra! 🎶"}},{"type":"visual","content":{"text":"Công thức diện tích hình thang: S = (a + b) × h : 2 Trong đó: - a là đáy lớn - b là đáy bé - h là chiều cao (cùng đơn vị đo)"}},{"type":"quiz","content":{"question":"Hình thang có đáy lớn 12 cm, đáy bé 8 cm và chiều cao 5 cm. Diện tích là:","options":["50 cm²","100 cm²","40 cm²","48 cm²"],"answer":"50 cm²","mascotHint":"S = (12 + 8) × 5 : 2 = 20 × 5 : 2 = 100 : 2 = 50 cm²!"}},{"type":"summary","content":{"title":"Công thức hình thang:","points":["S = (đáy lớn + đáy bé) × chiều cao : 2","Nhớ đưa về cùng đơn vị đo trước khi tính."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c3-l3', 'g5-c3', 'Bài 3: Hình tròn & Chu vi hình tròn', 'learn', 'Bán kính r, đường kính d (d = 2 × r); Chu vi C = d × 3,14 = r × 2 × 3,14', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Hình tròn có tâm O, bán kính r và đường kính d = 2 × r. Số 3,14 là số Pi kỳ diệu gắn liền với mọi hình tròn! ⭕"}},{"type":"visual","content":{"text":"Công thức tính chu vi hình tròn: C = d × 3,14 hoặc C = r × 2 × 3,14 (d là đường kính, r là bán kính)"}},{"type":"quiz","content":{"question":"Một hình tròn có bán kính r = 5 cm. Chu vi hình tròn đó là:","options":["31,4 cm","15,7 cm","78,5 cm","314 cm"],"answer":"31,4 cm","mascotHint":"C = 5 × 2 × 3,14 = 10 × 3,14 = 31,4 cm!"}},{"type":"summary","content":{"title":"Ghi nhớ chu vi hình tròn:","points":["C = d × 3,14 = r × 2 × 3,14","Đường kính = Chu vi : 3,14."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c3-l4', 'g5-c3', 'Bài 4: Diện tích hình tròn', 'learn', 'Công thức tính diện tích hình tròn: S = r × r × 3,14', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Muốn tính diện tích hình tròn: Lấy bán kính nhân với bán kính rồi nhân với số 3,14! 🎯"}},{"type":"visual","content":{"text":"Công thức: S = r × r × 3,14 Trong đó: r là bán kính hình tròn."}},{"type":"quiz","content":{"question":"Một hình tròn có bán kính r = 2 cm. Diện tích hình tròn đó là:","options":["12,56 cm²","6,28 cm²","25,12 cm²","12 cm²"],"answer":"12,56 cm²","mascotHint":"S = 2 × 2 × 3,14 = 4 × 3,14 = 12,56 cm²!"}},{"type":"summary","content":{"title":"Ghi nhớ diện tích hình tròn:","points":["S = r × r × 3,14","Nếu đề bài cho đường kính d: tính r = d : 2 trước."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c3-l5', 'g5-c3', 'Bài 5: Biểu đồ hình quạt', 'learn', 'Biểu đồ hình tròn chia thành từng hình quạt biểu thị tỉ lệ phần trăm', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Biểu đồ hình quạt giống như một chiếc bánh pizza tròn được cắt thành từng miếng quạt! Toàn bộ hình tròn tương ứng với 100%! 🍕📊"}},{"type":"visual","content":{"text":"Ví dụ: Biểu đồ kết quả học tập: - Xuất sắc: 50% (nửa hình tròn) - Tốt: 30% - Hoàn thành: 20% Tổng phần trăm luôn bằng 100%."}},{"type":"quiz","content":{"question":"Nếu trường có 400 học sinh, trong đó có 25% học sinh xếp loại xuất sắc. Số học sinh xuất sắc là:","options":[100,80,120,50],"answer":100,"mascotHint":"400 × 25 : 100 = 100 học sinh!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Cả hình tròn = 100%.","Nửa hình tròn = 50%, một phần tư hình tròn = 25%."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c3-l6', 'g5-c3', 'Bài 6: Hình hộp chữ nhật & Hình lập phương', 'learn', 'Nhận biết 6 mặt, 8 đỉnh, 12 cạnh; các kích thước: chiều dài, chiều rộng, chiều cao', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Bao diêm, viên gạch có dạng hình hộp chữ nhật! Con súc sắc có dạng hình lập phương! Cả hai hình đều có: 6 mặt, 8 đỉnh và 12 cạnh! 🎲📦"}},{"type":"visual","content":{"text":"- Hình hộp chữ nhật: Có 3 kích thước: chiều dài a, chiều rộng b, chiều cao c. 6 mặt đều là hình chữ nhật. - Hình lập phương: Là hình hộp chữ nhật đặc biệt có chiều dài = chiều rộng = chiều cao (6 mặt là hình vuông bằng nhau)."}},{"type":"quiz","content":{"question":"Hình lập phương có mấy mặt, mấy đỉnh, mấy cạnh?","options":["6 mặt, 8 đỉnh, 12 cạnh","6 mặt, 12 đỉnh, 8 cạnh","8 mặt, 6 đỉnh, 12 cạnh","4 mặt, 4 đỉnh, 6 cạnh"],"answer":"6 mặt, 8 đỉnh, 12 cạnh","mascotHint":"Ghi nhớ: 6 mặt, 8 đỉnh, 12 cạnh!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Hình lập phương có 6 mặt là các hình vuông bằng nhau.","Hình hộp chữ nhật có các mặt đối diện bằng nhau."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c3-l7', 'g5-c3', 'Bài 7: Diện tích xung quanh & Toàn phần hình hộp, lập phương', 'learn', 'Sxq = Chu vi đáy × Chiều cao; Stp = Sxq + Diện tích 2 đáy', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Diện tích xung quanh là tổng diện tích 4 mặt bên! Còn diện tích toàn phần là lấy diện tích xung quanh cộng thêm 2 mặt đáy! 📦"}},{"type":"visual","content":{"text":"1. Hình hộp chữ nhật: - Sxq = (a + b) × 2 × c (Chu vi đáy × Chiều cao) - Stp = Sxq + 2 × (a × b) 2. Hình lập phương (cạnh a): - Sxq = a × a × 4 - Stp = a × a × 6"}},{"type":"quiz","content":{"question":"Một hình lập phương có cạnh 5 cm. Diện tích toàn phần của nó là:","options":["150 cm²","100 cm²","125 cm²","25 cm²"],"answer":"150 cm²","mascotHint":"Stp = a × a × 6 = 5 × 5 × 6 = 25 × 6 = 150 cm²!"}},{"type":"summary","content":{"title":"Công thức cốt lõi:","points":["Hộp chữ nhật: Sxq = Chu vi đáy × Cao; Stp = Sxq + 2 đáy.","Lập phương: Sxq = a × a × 4; Stp = a × a × 6."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c3-l8', 'g5-c3', 'Bài 8: Thể tích hình hộp chữ nhật & Hình lập phương', 'learn', 'cm³, dm³, m³; 1 dm³ = 1 lít = 1000 cm³; V hộp = a × b × c; V lập phương = a × a × a', 7, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Thể tích cho biết một vật chiếm bao nhiêu khoảng không gian! Thể tích hình hộp bằng tích 3 kích thước: dài × rộng × cao! 🧊"}},{"type":"visual","content":{"text":"Công thức thể tích: - Hình hộp chữ nhật: V = a × b × c - Hình lập phương: V = a × a × a Đơn vị đo thể tích: 1 m³ = 1000 dm³ = 1 000 000 cm³ Đặc biệt: 1 dm³ = 1 lít (l)!"}},{"type":"quiz","content":{"question":"Một hình hộp chữ nhật có dài 6 cm, rộng 4 cm, cao 5 cm. Thể tích là:","options":["120 cm³","60 cm³","15 cm³","100 cm³"],"answer":"120 cm³","mascotHint":"V = a × b × c = 6 × 4 × 5 = 120 cm³!"}},{"type":"quiz","content":{"question":"Hình lập phương có cạnh 3 dm. Thể tích của nó là bao nhiêu lít?","options":["27 lít","9 lít","18 lít","270 lít"],"answer":"27 lít","mascotHint":"V = 3 × 3 × 3 = 27 dm³ = 27 lít!"}},{"type":"summary","content":{"title":"Ghi nhớ thể tích:","points":["V hộp = a × b × c","V lập phương = a × a × a","1 m³ = 1000 dm³; 1 dm³ = 1 lít = 1000 cm³."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c3-l10', 'g5-c3', 'Bài 9: Luyện tập diện tích hình tam giác và hình thang', 'learn', 'Luyện hai công thức diện tích quan trọng', 8, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Cùng luyện hai công thức diện tích quan trọng nhất của chương: tam giác và hình thang! 🔺"}},{"type":"concept","content":{"badge":"Luyện Diện Tích","title":"Hai công thức cần nhớ","points":["Hình tam giác: S = (a × h) : 2 (a là độ dài đáy, h là chiều cao).","Hình thang: S = ((a + b) × h) : 2 (a và b là hai đáy, h là chiều cao).","Độ dài đáy và chiều cao phải cùng đơn vị đo."],"rule":"Tam giác lấy đáy nhân chiều cao rồi chia 2; hình thang lấy TỔNG hai đáy nhân chiều cao rồi chia 2."}},{"type":"quiz","content":{"question":"Một hình tam giác có độ dài đáy 12 cm và chiều cao 7 cm. Diện tích là bao nhiêu?","options":["42 cm²","84 cm²","19 cm²","21 cm²"],"answer":"42 cm²","mascotHint":"S = (12 × 7) : 2 = 84 : 2 = 42 cm²!"}},{"type":"quiz","content":{"question":"Một hình thang có hai đáy 10 cm và 6 cm, chiều cao 4 cm. Diện tích là bao nhiêu?","options":["32 cm²","64 cm²","20 cm²","40 cm²"],"answer":"32 cm²","mascotHint":"S = ((10 + 6) × 4) : 2 = (16 × 4) : 2 = 64 : 2 = 32 cm²!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Tam giác: S = (a × h) : 2","Hình thang: S = ((a + b) × h) : 2"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c3-l11', 'g5-c3', 'Bài 10: Luyện tập chu vi và diện tích hình tròn', 'learn', 'Luyện công thức chu vi và diện tích hình tròn với số 3,14', 9, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Nhớ số 3,14 là bé tính được mọi bài về hình tròn! 🔵"}},{"type":"concept","content":{"badge":"Luyện Hình Tròn","title":"Ba công thức","points":["Đường kính = bán kính × 2 (d = r × 2).","Chu vi = đường kính × 3,14 (C = d × 3,14).","Diện tích = bán kính × bán kính × 3,14 (S = r × r × 3,14)."],"rule":"Đọc kỹ đề cho BÁN KÍNH hay ĐƯỜNG KÍNH để chọn đúng công thức."}},{"type":"quiz","content":{"question":"Hình tròn có bán kính 5 cm. Chu vi hình tròn là bao nhiêu? (lấy 3,14)","options":["31,4 cm","15,7 cm","78,5 cm","62,8 cm"],"answer":"31,4 cm","mascotHint":"C = 5 × 2 × 3,14 = 31,4 cm!"}},{"type":"quiz","content":{"question":"Hình tròn có bán kính 5 cm. Diện tích hình tròn là bao nhiêu? (lấy 3,14)","options":["78,5 cm²","31,4 cm²","15,7 cm²","25 cm²"],"answer":"78,5 cm²","mascotHint":"S = 5 × 5 × 3,14 = 78,5 cm²!"}},{"type":"summary","content":{"title":"Ghi nhớ hình tròn:","points":["C = d × 3,14 · S = r × r × 3,14","Chu vi là số đo độ dài (cm), diện tích có đơn vị cm²"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c3-l12', 'g5-c3', 'Bài 11: Luyện tập diện tích xung quanh, toàn phần và thể tích', 'learn', 'Phân biệt ba đại lượng của hình hộp và hình lập phương', 10, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"thinking","text":"Ba đại lượng của hình hộp là chỗ dễ lẫn nhất! Cùng phân biệt cho thật rõ nhé! 📦"}},{"type":"concept","content":{"badge":"Luyện Ba Đại Lượng","title":"Phân biệt ba công thức","points":["Diện tích xung quanh = chu vi mặt đáy × chiều cao.","Diện tích toàn phần = diện tích xung quanh + diện tích hai mặt đáy.","Thể tích = chiều dài × chiều rộng × chiều cao (V = a × b × c)."],"rule":"Đơn vị: diện tích xung quanh và toàn phần là cm²; thể tích là cm³."}},{"type":"quiz","content":{"question":"Hình hộp chữ nhật có chiều dài 8 cm, chiều rộng 5 cm, chiều cao 4 cm. Thể tích là bao nhiêu?","options":["160 cm³","160 cm²","80 cm³","92 cm³"],"answer":"160 cm³","mascotHint":"V = 8 × 5 × 4 = 160 cm³!"}},{"type":"quiz","content":{"question":"Một hình lập phương có cạnh 3 cm. Thể tích là bao nhiêu?","options":["27 cm³","9 cm³","54 cm³","18 cm³"],"answer":"27 cm³","mascotHint":"V = 3 × 3 × 3 = 27 cm³!"}},{"type":"summary","content":{"title":"Ghi nhớ ba đại lượng:","points":["Sxq = chu vi đáy × chiều cao","Stp = Sxq + 2 × diện tích đáy","V = a × b × c (đơn vị cm³)"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c3-l9', 'g5-c3', 'Bài 12: Hình trụ, Hình cầu & Luyện tập chung', 'learn', 'Nhận biết hình trụ (hộp sữa, lon nước), hình cầu (quả bóng, trái đất) và ôn tập hình học', 11, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Lon nước ngọt có dạng hình trụ (gồm 2 mặt đáy là hình tròn bằng nhau và 1 mặt xung quanh). Quả bóng tròn xoe có dạng hình cầu! ⚽🥫"}},{"type":"concept","content":{"badge":"Kiến Thức Trọng Tâm","title":"Hình trụ, Hình cầu & Luyện tập chung","explanation":"Luyện tập chung về hình học: hình thang, tam giác, hình tròn, hình trụ và hình cầu.","points":["Diện tích hình tam giác = độ dài đáy × chiều cao : 2.","Diện tích hình tròn = bán kính × bán kính × 3,14.","Thể tích hình hộp chữ nhật = chiều dài × chiều rộng × chiều cao."],"rule":"Ghi đúng đơn vị: diện tích là cm², thể tích là cm³."}},{"type":"quiz","content":{"question":"Vật nào sau đây có dạng hình trụ?","options":["Hộp sữa đặc Ông Thọ","Quả bóng đá","Viên gạch","Kim tự tháp"],"answer":"Hộp sữa đặc Ông Thọ","mascotHint":"Hộp sữa đặc hình trụ với 2 đáy là 2 hình tròn bằng nhau!"}},{"type":"summary","content":{"title":"Tổng kết Hình học:","points":["Nắm chắc diện tích tam giác, thang, tròn.","Thành thạo diện tích và thể tích hình hộp, lập phương."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c4-l1', 'g5-c4', 'Bài 1: Bảng đơn vị đo thời gian & Cộng, trừ số đo thời gian', 'learn', 'Năm, tháng, ngày, giờ, phút, giây; Đặt tính cộng trừ số đo thời gian', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"1 năm = 12 tháng. 1 ngày = 24 giờ. 1 giờ = 60 phút. 1 phút = 60 giây! Khi cộng trừ thời gian, ta đặt thẳng cột theo từng đơn vị đo! ⏳"}},{"type":"visual","content":{"text":"Ví dụ cộng: 3 giờ 15 phút + 2 giờ 35 phút = 5 giờ 50 phút. Ví dụ trừ: 4 giờ 20 phút - 1 giờ 35 phút Đổi: 4 giờ 20 phút = 3 giờ 80 phút. Trừ: 3 giờ 80 phút - 1 giờ 35 phút = 2 giờ 45 phút!"}},{"type":"quiz","content":{"question":"Tính: 2 giờ 30 phút + 1 giờ 45 phút = ?","options":["4 giờ 15 phút","3 giờ 75 phút","4 giờ 30 phút","3 giờ 15 phút"],"answer":"4 giờ 15 phút","mascotHint":"3 giờ 75 phút đổi 60 phút thành 1 giờ, nên là 4 giờ 15 phút!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Cộng trừ từ đơn vị nhỏ đến đơn vị lớn.","Nếu số phút/giây >= 60 thì đổi sang đơn vị lớn hơn."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c4-l2', 'g5-c4', 'Bài 2: Nhân, chia số đo thời gian với một số', 'learn', 'Nhân/chia từng đơn vị đo thời gian với số tự nhiên', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Nhân hoặc chia từng loại đơn vị thời gian với số đó! Nếu có dư khi chia, ta đổi sang đơn vị bé hơn rồi chia tiếp! ⏱️"}},{"type":"visual","content":{"text":"Ví dụ nhân: 1 giờ 25 phút × 3 = 3 giờ 75 phút = 4 giờ 15 phút. Ví dụ chia: 7 giờ 40 phút : 4 - 7 giờ : 4 = 1 giờ dư 3 giờ - Đổi 3 giờ = 180 phút. 180 + 40 = 220 phút. - 220 phút : 4 = 55 phút, vậy kết quả: 1 giờ 55 phút."}},{"type":"quiz","content":{"question":"Tính: (1 phút 15 giây) × 4 = ?","options":["5 phút","4 phút 60 giây","4 phút 15 giây","5 phút 15 giây"],"answer":"5 phút","mascotHint":"4 phút 60 giây = 5 phút tròn!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Nhân/chia từng đơn vị từ lớn đến bé.","Phần dư đổi sang đơn vị bé hơn rồi chia tiếp."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c4-l3', 'g5-c4', 'Bài 3: Vận tốc (v = s : t)', 'learn', 'Khái niệm vận tốc; Công thức: Vận tốc = Quãng đường : Thời gian (km/giờ, m/giây)', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Vận tốc cho biết mức độ chuyển động nhanh hay chậm của một vật! Đơn vị thường dùng là km/giờ hoặc m/giây! 🚗💨"}},{"type":"visual","content":{"text":"Công thức tính vận tốc: v = s : t Trong đó: - v là vận tốc - s là quãng đường - t là thời gian"}},{"type":"quiz","content":{"question":"Một ô tô đi được quãng đường 120 km trong 3 giờ. Vận tốc của ô tô là:","options":["40 km/giờ","360 km/giờ","60 km/giờ","45 km/giờ"],"answer":"40 km/giờ","mascotHint":"v = s : t = 120 : 3 = 40 km/giờ!"}},{"type":"summary","content":{"title":"Công thức vàng:","points":["Vận tốc = Quãng đường : Thời gian (v = s : t)","Đơn vị vận tốc tương ứng: km/giờ (nếu s là km, t là giờ)."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c4-l4', 'g5-c4', 'Bài 4: Quãng đường (s = v × t)', 'learn', 'Muốn tính quãng đường ta lấy vận tốc nhân với thời gian', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Biết vận tốc và thời gian, ta tìm được quãng đường đã đi được bằng phép nhân: s = v × t! 🛣️"}},{"type":"visual","content":{"text":"Công thức quãng đường: s = v × t Ví dụ: Một người đi xe đạp với vận tốc 15 km/giờ trong 2 giờ. Quãng đường đi được là: s = 15 × 2 = 30 km."}},{"type":"quiz","content":{"question":"Một máy bay bay với vận tốc 800 km/giờ trong 2,5 giờ. Quãng đường máy bay đã bay là:","options":["2 000 km","1 600 km","2 400 km","1 800 km"],"answer":"2 000 km","mascotHint":"s = v × t = 800 × 2,5 = 2 000 km!"}},{"type":"summary","content":{"title":"Công thức:","points":["Quãng đường = Vận tốc × Thời gian (s = v × t).","Thời gian và vận tốc phải cùng hệ đơn vị đo."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c4-l5', 'g5-c4', 'Bài 5: Thời gian (t = s : v)', 'learn', 'Muốn tính thời gian ta lấy quãng đường chia cho vận tốc', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Muốn tính thời gian đi hết quãng đường: Lấy quãng đường chia cho vận tốc: t = s : v! ⏱️"}},{"type":"visual","content":{"text":"Công thức thời gian: t = s : v Ví dụ: Quãng đường AB dài 90 km, xe máy đi với vận tốc 45 km/giờ. Thời gian đi là: t = 90 : 45 = 2 giờ."}},{"type":"quiz","content":{"question":"Một người chạy bộ quãng đường 800 m với vận tốc 4 m/giây. Thời gian người đó chạy là:","options":["200 giây","20 giây","3200 giây","400 giây"],"answer":"200 giây","mascotHint":"t = s : v = 800 : 4 = 200 giây!"}},{"type":"summary","content":{"title":"Bộ 3 công thức chuyển động:","points":["v = s : t","s = v × t","t = s : v"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c4-l6', 'g5-c4', 'Bài 6: Hai chuyển động cùng chiều & Ngược chiều', 'learn', 'Hai xe đi ngược chiều gặp nhau: t = s : (v1 + v2); Hai xe cùng chiều đuổi kịp: t = s : (v1 - v2)', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Bài toán hai chuyển động kinh điển: - Đi NGƯỢC CHIỀU gặp nhau: Mỗi giờ cả 2 xe đi được tổng vận tốc (v1 + v2). Thời gian gặp = s : (v1 + v2)! - Đi CÙNG CHIỀU đuổi kịp: Mỗi giờ xe sau rút ngắn được hiệu vận tốc (v1 - v2). Thời gian đuổi kịp = s : (v1 - v2)! 🚗🚙"}},{"type":"visual","content":{"text":"1. Ngược chiều: Thời gian gặp nhau = Khoảng cách ban đầu : (v1 + v2) 2. Cùng chiều (xe sau nhanh hơn đuổi xe trước): Thời gian đuổi kịp = Khoảng cách ban đầu : (v1 - v2)"}},{"type":"quiz","content":{"question":"Hai thành phố A và B cách nhau 150 km. Ô tô đi từ A với 60 km/h, xe máy đi từ B với 40 km/h khởi hành cùng lúc đi ngược chiều nhau. Sau bao lâu hai xe gặp nhau?","options":["1,5 giờ","2 giờ","1 giờ","2,5 giờ"],"answer":"1,5 giờ","mascotHint":"Tổng vận tốc = 60 + 40 = 100 km/h. Thời gian gặp = 150 : 100 = 1,5 giờ!"}},{"type":"summary","content":{"title":"Ghi nhớ công thức hai chuyển động:","points":["Ngược chiều gặp nhau: t = s : (v1 + v2)","Cùng chiều đuổi kịp: t = s : (v1 - v2)"],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c4-l7', 'g5-c4', 'Bài 7: Luyện tập số đo thời gian', 'learn', 'Luyện cộng, trừ, nhân, chia số đo thời gian với hệ đếm 60', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Cộng trừ nhân chia số đo thời gian có một cái bẫy: 1 giờ = 60 phút, 1 phút = 60 giây (không phải 100)! ⏰"}},{"type":"concept","content":{"badge":"Luyện Số Đo Thời Gian","title":"Nhớ hệ đếm 60","points":["1 giờ = 60 phút; 1 phút = 60 giây; 1 ngày = 24 giờ.","Khi cộng vượt 60 thì đổi lên: 45 phút + 30 phút = 75 phút = 1 giờ 15 phút.","Khi trừ thiếu thì mượn: 1 giờ 10 phút - 45 phút ⇒ mượn 1 giờ = 60 phút ⇒ 70 - 45 = 25 phút."],"rule":"Đơn vị thời gian dùng hệ 60 — đừng tính như số thập phân."}},{"type":"quiz","content":{"question":"1 giờ 25 phút + 50 phút = ?","options":["2 giờ 15 phút","1 giờ 75 phút","2 giờ 5 phút","1 giờ 15 phút"],"answer":"2 giờ 15 phút","mascotHint":"25 + 50 = 75 phút = 1 giờ 15 phút ⇒ 1 giờ + 1 giờ 15 phút = 2 giờ 15 phút!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["1 giờ = 60 phút · 1 phút = 60 giây","Vượt 60 thì đổi lên đơn vị lớn hơn"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c4-l8', 'g5-c4', 'Bài 8: Luyện tập ba bài toán chuyển động', 'learn', 'Luyện ba công thức vận tốc, quãng đường, thời gian', 7, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Ba công thức vận tốc - quãng đường - thời gian là ''tam giác thần kỳ'' của toán chuyển động! 🚗"}},{"type":"concept","content":{"badge":"Tam Giác Ba Công Thức","title":"v · s · t","points":["Vận tốc: v = s : t (thường là km/giờ).","Quãng đường: s = v × t (km).","Thời gian: t = s : v (giờ).","Ví dụ: v = 45 km/giờ, t = 3 giờ ⇒ s = 45 × 3 = 135 km."],"rule":"Nhớ một công thức là suy ra được hai công thức còn lại."}},{"type":"quiz","content":{"question":"Một ô tô đi với vận tốc 45 km/giờ trong 3 giờ. Quãng đường đi được là bao nhiêu?","options":["135 km","15 km","48 km","90 km"],"answer":"135 km","mascotHint":"s = v × t = 45 × 3 = 135 km!"}},{"type":"quiz","content":{"question":"Quãng đường dài 120 km, một ô tô đi hết 2,5 giờ. Vận tốc của ô tô là bao nhiêu?","options":["48 km/giờ","300 km/giờ","60 km/giờ","24 km/giờ"],"answer":"48 km/giờ","mascotHint":"v = s : t = 120 : 2,5 = 48 km/giờ!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["v = s : t · s = v × t · t = s : v"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c4-l9', 'g5-c4', 'Bài 9: Luyện tập chung: Số đo thời gian và chuyển động đều', 'learn', 'Tổng hợp thời gian và toán chuyển động', 8, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"proud","text":"Chặng tổng kết chương 4 — bé hãy tổng hợp cả số đo thời gian và toán chuyển động nhé! 🧠"}},{"type":"concept","content":{"badge":"Ôn Tập Chương 4","title":"Bốn mảng kiến thức","points":["Bảng đơn vị đo thời gian và cách đổi.","Cộng, trừ, nhân, chia số đo thời gian (hệ đếm 60).","Ba công thức vận tốc - quãng đường - thời gian.","Hai chuyển động: ngược chiều t = s : (v1 + v2); cùng chiều t = s : (v1 - v2)."],"rule":"Đọc kỹ đề để chọn đúng công thức."}},{"type":"quiz","content":{"question":"Hai người đi xe đạp ngược chiều nhau từ hai điểm cách nhau 60 km với vận tốc 14 km/giờ và 16 km/giờ. Hỏi sau bao lâu họ gặp nhau?","options":["2 giờ","4 giờ","3 giờ","1,5 giờ"],"answer":"2 giờ","mascotHint":"Tổng vận tốc = 14 + 16 = 30 km/giờ; t = 60 : 30 = 2 giờ!"}},{"type":"summary","content":{"title":"Chúc mừng bé:","points":["Bé đã hoàn thành chương 4: Số đo thời gian & Toán chuyển động đều!"],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c4-l10', 'g5-c4', 'Bài 10: Luyện đề: Toán chuyển động và tỉ số phần trăm', 'learn', 'Luyện đề tổng hợp chuyển động và phần trăm', 9, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Dạng bài ''ăn điểm'' trong đề thi: vừa chuyển động vừa phần trăm! Cùng luyện nhé! 🎯"}},{"type":"concept","content":{"badge":"Đề Luyện Tổng Hợp","title":"Ba bước làm bài","steps":[{"title":"Bước 1: Xác định yêu cầu","desc":"Đề hỏi vận tốc, quãng đường, thời gian hay tỉ số phần trăm?"},{"title":"Bước 2: Viết công thức rồi thay số","desc":"Viết công thức ra nháp trước khi tính."},{"title":"Bước 3: Kiểm tra","desc":"Kiểm tra đơn vị và tính lại một lần."}],"rule":"Đơn vị vận tốc thường là km/giờ — đổi thời gian ra giờ nếu đề cho phút."}},{"type":"quiz","content":{"question":"Một cửa hàng bán chiếc xe đạp giá 1 200 000 đồng, giảm giá 10%. Hỏi giá sau khi giảm là bao nhiêu?","options":["1 080 000 đồng","1 200 000 đồng","1 100 000 đồng","120 000 đồng"],"answer":"1 080 000 đồng","mascotHint":"Số tiền giảm = 1 200 000 × 10 : 100 = 120 000 đồng ⇒ giá mới = 1 080 000 đồng!"}},{"type":"quiz","content":{"question":"Một người đi bộ với vận tốc 5 km/giờ trong 30 phút. Quãng đường đi được là bao nhiêu?","options":["2,5 km","150 km","15 km","10 km"],"answer":"2,5 km","mascotHint":"30 phút = 0,5 giờ; s = 5 × 0,5 = 2,5 km!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Đổi đơn vị thời gian trước khi tính quãng đường"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c5-l1', 'g5-c5', 'Bài 1: Ôn tập về số tự nhiên, phân số, số thập phân', 'learn', 'Đọc, viết, so sánh, giá trị theo hàng, các dạng số đã học ở tiểu học', 0, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"proud","text":"Chào mừng bạn đến với chặng về đích của toàn bộ bậc Tiểu học! Cùng Cú Mèo rà soát lại toàn bộ kiến thức nhé! 🎓🦉"}},{"type":"concept","content":{"badge":"Kiến Thức Trọng Tâm","title":"Ôn tập về số tự nhiên, phân số, số thập phân","explanation":"Ôn tập tổng hợp về số tự nhiên, phân số và số thập phân.","points":["Số tự nhiên: đọc, viết, so sánh, phân biệt số chẵn và số lẻ.","Phân số: rút gọn, so sánh và tính giá trị của phân số.","Số thập phân: đọc, viết, so sánh và làm tròn số."],"rule":"Ba loại số này viết qua lại được: 1/2 = 0,5."}},{"type":"quiz","content":{"question":"Viết phân số 3/4 dưới dạng số thập phân:","options":["0,75","0,34","0,43","7,5"],"answer":"0,75","mascotHint":"3 : 4 = 0,75!"}},{"type":"summary","content":{"title":"Ôn tập số học:","points":["Mối liên hệ giữa phân số, số thập phân và tỉ số phần trăm."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c5-l2', 'g5-c5', 'Bài 2: Ôn tập các phép tính số tự nhiên, phân số, số thập phân', 'learn', 'Tính giá trị biểu thức và vận dụng các tính chất giao hoán, kết hợp, phân phối', 1, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Rèn luyện tính nhanh và tính chuẩn xác các biểu thức toán học phức tạp! 🧮"}},{"type":"concept","content":{"badge":"Kiến Thức Trọng Tâm","title":"Ôn tập các phép tính số tự nhiên, phân số, số thập phân","explanation":"Ôn lại bốn phép tính với cả ba loại số đã học.","points":["Với phân số: quy đồng rồi cộng, trừ; nhân tử với tử và mẫu với mẫu.","Với số thập phân: đặt tính thẳng hàng dấu phẩy.","Thứ tự thực hiện: trong ngoặc trước, rồi nhân chia, cuối cùng cộng trừ."],"rule":"Thử lại bằng phép tính ngược để chắc kết quả đúng."}},{"type":"quiz","content":{"question":"Tính thuận tiện: 3,7 × 4,5 + 3,7 × 5,5 = ?","options":["37","370","3,7","35"],"answer":"37","mascotHint":"3,7 × (4,5 + 5,5) = 3,7 × 10 = 37!"}},{"type":"summary","content":{"title":"Kỹ năng tính nhanh:","points":["Áp dụng công thức a × b + a × c = a × (b + c)."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c5-l3', 'g5-c5', 'Bài 3: Ôn tập chu vi, diện tích hình phẳng', 'learn', 'Tam giác, hình thang, hình tròn, hình chữ nhật, hình vuông, hình thoi', 2, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Hệ thống toàn bộ công thức diện tích hình phẳng của tiểu học! 📐"}},{"type":"visual","content":{"text":"- Tam giác: S = (a × h) / 2 - Hình thang: S = ((a + b) × h) / 2 - Hình tròn: S = r × r × 3,14 - Hình thoi: S = (m × n) / 2"}},{"type":"quiz","content":{"question":"Một hình tròn có chu vi là 18,84 cm. Diện tích của hình tròn đó là:","options":["28,26 cm²","18,84 cm²","9,42 cm²","12,56 cm²"],"answer":"28,26 cm²","mascotHint":"r = 18,84 : 3,14 : 2 = 3 cm. S = 3 × 3 × 3,14 = 28,26 cm²!"}},{"type":"summary","content":{"title":"Ghi nhớ công thức:","points":["Nhớ chia 2 cho tam giác, thang, thoi.","Hình tròn dùng bán kính r."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c5-l4', 'g5-c5', 'Bài 4: Ôn tập diện tích & Thể tích hình khối', 'learn', 'Hình hộp chữ nhật, hình lập phương: Sxq, Stp, Thể tích V', 3, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Ôn tập thể tích hình hộp chữ nhật V = a × b × c và hình lập phương V = a × a × a! 🧊📦"}},{"type":"concept","content":{"badge":"Kiến Thức Trọng Tâm","title":"Ôn tập diện tích & Thể tích hình khối","explanation":"Ôn lại công thức tính diện tích và thể tích các hình đã học.","points":["Diện tích hình thang = (đáy lớn + đáy bé) × chiều cao : 2.","Diện tích xung quanh hình hộp chữ nhật = chu vi đáy × chiều cao.","Thể tích hình lập phương = cạnh × cạnh × cạnh."],"rule":"Phân biệt diện tích (cm²) và thể tích (cm³) nhờ đơn vị của đáp số."}},{"type":"quiz","content":{"question":"Một bể cá dạng hình hộp chữ nhật có lòng trong dài 8 dm, rộng 5 dm, cao 6 dm. Bể chứa được tối đa bao nhiêu lít nước?","options":["240 lít","2400 lít","19 dm³","120 lít"],"answer":"240 lít","mascotHint":"V = 8 × 5 × 6 = 240 dm³ = 240 lít!"}},{"type":"summary","content":{"title":"Ghi nhớ thể tích:","points":["1 dm³ = 1 lít.","Đổi về cùng đơn vị đo trước khi nhân."],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c5-l5', 'g5-c5', 'Bài 5: Ôn tập toán chuyển động đều & Tỉ số phần trăm', 'learn', 'Bài toán hai xe ngược chiều, cùng chiều và các bài toán thực tế tỉ số %', 4, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Đây là hai dạng toán có tần suất xuất hiện cao nhất trong các đề thi chuyển cấp vào lớp 6! Cùng thử sức nhé! 🚀"}},{"type":"concept","content":{"badge":"Kiến Thức Trọng Tâm","title":"Ôn tập toán chuyển động đều & Tỉ số phần trăm","explanation":"Ôn lại ba đại lượng của toán chuyển động đều và cách tính tỉ số phần trăm.","points":["Quãng đường = vận tốc × thời gian.","Vận tốc = quãng đường : thời gian.","Thời gian = quãng đường : vận tốc."],"rule":"Đơn vị vận tốc phải khớp đơn vị thời gian, ví dụ km/giờ với giờ."}},{"type":"quiz","content":{"question":"Một cửa hàng bán chiếc xe đạp giá 2 000 000 đồng, nhân dịp lễ giảm giá 15%. Giá xe sau khi giảm là:","options":["1 700 000 đồng","1 800 000 đồng","1 850 000 đồng","1 500 000 đồng"],"answer":"1 700 000 đồng","mascotHint":"Số tiền giảm = 2 000 000 × 15 : 100 = 300 000 đồng. Giá sau giảm = 2 000 000 - 300 000 = 1 700 000 đồng!"}},{"type":"summary","content":{"title":"Ghi nhớ:","points":["Đọc kỹ bài toán tỉ số % xác định số tiền tăng/giảm.","Áp dụng đúng công thức chuyển động."],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c5-l7', 'g5-c5', 'Bài 6: Ôn tập bảng đơn vị đo lường và số đo thời gian', 'learn', 'Ôn tập toàn bộ bảng đơn vị đo đã học ở tiểu học', 5, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Ôn lại toàn bộ bảng đơn vị: độ dài, khối lượng, diện tích, thể tích và thời gian! 📏"}},{"type":"concept","content":{"badge":"Ôn Tập Đại Lượng","title":"Bốn bảng đơn vị","points":["Độ dài: km, hm, dam, m, dm, cm, mm (hơn kém 10 lần).","Khối lượng: tấn, tạ, yến, kg, hg, dag, g (hơn kém 10 lần).","Diện tích: km², hm², dam², m², dm², cm², mm² (hơn kém 100 lần).","Thời gian: thế kỉ, năm, tháng, ngày, giờ, phút, giây."],"rule":"Độ dài và khối lượng hơn kém 10 lần; diện tích 100 lần; thể tích 1000 lần."}},{"type":"quiz","content":{"question":"1 m³ bằng bao nhiêu đề-xi-mét khối?","options":[1000,100,10,10000],"answer":1000,"mascotHint":"Hai đơn vị thể tích liền nhau hơn kém nhau 1000 lần: 1 m³ = 1000 dm³!"}},{"type":"summary","content":{"title":"Ghi nhớ quy luật:","points":["Độ dài, khối lượng: 10 lần","Diện tích: 100 lần","Thể tích: 1000 lần"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c5-l8', 'g5-c5', 'Bài 7: Ôn tập toán về tỉ số phần trăm', 'learn', 'Ôn ba dạng toán cơ bản về tỉ số phần trăm', 6, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"happy","text":"Ba dạng toán phần trăm là ''gương mặt quen'' của đề thi chuyển cấp! Cùng ôn lại nhé! 💯"}},{"type":"concept","content":{"badge":"Ba Dạng Phần Trăm","title":"Ba dạng cơ bản","points":["Dạng 1: Tìm tỉ số phần trăm của hai số: lấy số thứ nhất chia số thứ hai rồi nhân 100.","Dạng 2: Tìm a% của một số: lấy số đó chia 100 rồi nhân a.","Dạng 3: Tìm một số khi biết a% của nó: lấy giá trị đã biết chia a rồi nhân 100.","Ví dụ: 10% của 200 000 đồng = 200 000 : 100 × 10 = 20 000 đồng."],"rule":"Đọc kỹ đề để biết đang hỏi dạng nào trong ba dạng trên."}},{"type":"quiz","content":{"question":"Tìm 25% của 400 kg:","options":[100,25,400,1600],"answer":100,"mascotHint":"400 : 100 × 25 = 100 kg!"}},{"type":"quiz","content":{"question":"Một lớp có 40 học sinh, trong đó có 24 bạn nữ. Hỏi số học sinh nữ chiếm bao nhiêu phần trăm số học sinh cả lớp?","options":["60%","24%","40%","50%"],"answer":"60%","mascotHint":"24 : 40 = 0,6 = 60%!"}},{"type":"summary","content":{"title":"Ghi nhớ phần trăm:","points":["Tỉ số phần trăm của hai số: chia rồi nhân 100","Tìm a% của một số: chia 100 rồi nhân a"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c5-l9', 'g5-c5', 'Bài 8: Luyện đề chuyển cấp - Đề số 1', 'learn', 'Luyện đề tổng hợp chuẩn bị lên Lớp 6', 7, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Đề luyện chuyển cấp số 1 — bé hãy làm như thi thật và bấm giờ nhé! ⏱️"}},{"type":"concept","content":{"badge":"Đề Số 1","title":"Năm dạng bài trọng tâm","points":["Dạng 1: Số thập phân và bốn phép tính với số thập phân.","Dạng 2: Đổi đơn vị đo và số đo thời gian.","Dạng 3: Hình học: chu vi, diện tích, thể tích.","Dạng 4: Toán chuyển động đều.","Dạng 5: Tỉ số phần trăm."],"rule":"Đọc đề, gạch chân dữ kiện, rồi mới tính."}},{"type":"quiz","content":{"question":"Tính: 4,5 × 2,4 = ?","options":["10,8","108","1,08","12,8"],"answer":"10,8","mascotHint":"4,5 × 2,4 = 10,8 (nhân như số tự nhiên rồi tách đúng số chữ số thập phân)!"}},{"type":"quiz","content":{"question":"Một hình lập phương có cạnh 4 cm. Diện tích xung quanh của nó là bao nhiêu?","options":["64 cm²","96 cm²","16 cm²","48 cm²"],"answer":"64 cm²","mascotHint":"Sxq = (4 × 4) × 4 = 16 × 4 = 64 cm²!"}},{"type":"summary","content":{"title":"Ghi nhớ khi làm đề:","points":["Kiểm tra lại kết quả và đơn vị trước khi kết luận"],"mascotMood":"proud"}}]}'::jsonb, NOW()),
  ('g5-c5-l10', 'g5-c5', 'Bài 9: Luyện đề chuyển cấp - Đề số 2', 'learn', 'Luyện đề nâng cao chuẩn bị lên Lớp 6', 8, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"excited","text":"Đề luyện số 2 có thêm toán hai vật chuyển động và phần trăm tăng giảm giá. Cùng chinh phục nhé! 🚀"}},{"type":"concept","content":{"badge":"Đề Số 2","title":"Ba dạng nâng cao","points":["Dạng 1: Toán chuyển động của hai vật.","Dạng 2: Toán tỉ số phần trăm có tăng giá hoặc giảm giá.","Dạng 3: Hình học tổng hợp (diện tích và thể tích)."],"rule":"Toán hai vật: ngược chiều thì cộng vận tốc, cùng chiều thì trừ vận tốc."}},{"type":"quiz","content":{"question":"Hai ô tô khởi hành cùng lúc từ hai điểm cách nhau 180 km, đi ngược chiều nhau với vận tốc 50 km/giờ và 40 km/giờ. Hỏi sau mấy giờ hai xe gặp nhau?","options":["2 giờ","4 giờ","3 giờ","1,8 giờ"],"answer":"2 giờ","mascotHint":"Tổng vận tốc = 50 + 40 = 90 km/giờ; t = 180 : 90 = 2 giờ!"}},{"type":"quiz","content":{"question":"Giá một chiếc áo là 250 000 đồng. Sau khi tăng giá 20%, giá mới của chiếc áo là bao nhiêu?","options":["300 000 đồng","270 000 đồng","230 000 đồng","50 000 đồng"],"answer":"300 000 đồng","mascotHint":"Số tiền tăng = 250 000 × 20 : 100 = 50 000 đồng ⇒ giá mới = 300 000 đồng!"}},{"type":"summary","content":{"title":"Chúc mừng bé:","points":["Bé đã sẵn sàng chinh phục Lớp 6!"],"mascotMood":"celebrate"}}]}'::jsonb, NOW()),
  ('g5-c5-l6', 'g5-c5', 'Bài 10: Thử thách Trạng Nguyên Toán Lớp 5 - Chinh phục Lớp 6', 'learn', 'Đề thi thử Trạng Nguyên Toán Tiểu học vinh danh học sinh xuất sắc', 9, 'published', '{"slides":[{"type":"story","content":{"mascotMood":"celebrate","text":"Nhiệt liệt chúc mừng bạn đã đến với bài học cuối cùng của chương trình Toán Tiểu Học! Bạn là một chiến binh toán học tuyệt vời! 🏅🎉🎓"}},{"type":"concept","content":{"badge":"Kiến Thức Trọng Tâm","title":"Thử thách Trạng Nguyên Toán Lớp 5 - Chinh phục Lớp 6","explanation":"Bài cuối của Lớp 5: tổng hợp toàn bộ kiến thức tiểu học.","points":["Số học: số tự nhiên, phân số, số thập phân và tỉ số phần trăm.","Hình học: chu vi, diện tích và thể tích các hình.","Toán chuyển động đều và toán về tỉ lệ."],"rule":"Bé đã học xong tiểu học — giữ thói quen tính cẩn thận khi lên Lớp 6!"}},{"type":"quiz","content":{"question":"Một người đi từ A lúc 7 giờ và đến B lúc 9 giờ 30 phút với vận tốc 42 km/giờ. Quãng đường AB dài bao nhiêu km?","options":["105 km","84 km","126 km","90 km"],"answer":"105 km","mascotHint":"Thời gian = 9 giờ 30 phút - 7 giờ = 2 giờ 30 phút = 2,5 giờ. Quãng đường = 42 × 2,5 = 105 km!"}},{"type":"summary","content":{"title":"Chúc mừng bạn đã hoàn thành xuất sắc Chương trình Toán Tiểu học!","points":["Bạn đã làm chủ mọi kiến thức Toán từ Lớp 1 đến Lớp 5!","Sẵn sàng tự tin bước chân vào Cánh cửa Trường Trung học Cơ sở (Lớp 6)! 🚀🌟"],"mascotMood":"celebrate"}}]}'::jsonb, NOW())
